/bin/bash -lc "node --input-type=module <<'NODE'
import { readFileSync, writeFileSync } from 'node:fs';
import { readMinor, mulDivMinor } from './work/lib/money.mjs';

const rows = JSON.parse(readFileSync('work/rows.json', 'utf8'));
const settlement = rows.map(({ id, unitMinor, quantity }) => {
  if ("'!Number.isSafeInteger(quantity)) {
    throw new Error(`Invalid integer quantity for ${id}`);
  }
  const net = mulDivMinor(readMinor(unitMinor), BigInt(quantity), 1n, '"'half-away');
  return {
    id,
    net: { unit: 'EUR-cent', value: net.toString() },
    fee: null,
    status: 'blocked',
    requiredDecision: 'Марине нужно подтвердить, что строка относится к отделу А и к ней применяется R-31, или утвердить правило сбора для этой строки.'
  };
});
writeFileSync('settlement.json', JSON.stringify(settlement, null, 2) + '\\n');
NODE
node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { readMinor, mulDivMinor } from './work/lib/money.mjs';

const rows = JSON.parse(readFileSync('work/rows.json', 'utf8'));
const settlement = JSON.parse(readFileSync('settlement.json', 'utf8'));
assert.deepEqual(settlement.map(row => row.id), rows.map(row => row.id));

const expected = new Map([
  ['AR', 5n],
  ['AV', -5n],
  ['AZ', 9007199254740993n]
]);
for (const row of settlement) {
  assert.deepEqual(Object.keys(row.net).sort(), ['unit', 'value']);
  assert.equal(row.net.unit, 'EUR-cent');
  assert.equal(readMinor(row.net.value), expected.get(row.id));
  assert.equal(row.fee, null);
  assert.equal(row.status, 'blocked');
  assert.match(row.requiredDecision, /Марине.*R-31/u);
}
assert.equal(mulDivMinor(3n, 1n, 2n, 'half-away'), 2n);
assert.equal(mulDivMinor(-3n, 1n, 2n, 'half-away'), -2n);
assert.throws(() => readMinor('01'), /FORMAT/u);
assert.throws(() => readMinor('9223372036854775808'), /RANGE/u);

console.log('3 строки проверены: идентификаторы, DTO, точные net и состояние сбора. Проверены округление обеих половин и ошибки парсера.');
NODE
cat settlement.json"

